1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    :root {
9	      --color-white: #ffffff;
10	      --color-gold: #ffd700;
11	      --color-pink: #ff6b9d;
12	      --color-teal: #4ecdc4;
13	      --color-mint: #95e1d3;
14	      --shadow-color: rgba(0, 0, 0, 0.3);
15	      --transition-normal: 0.3s ease;
16	      --transition-slow: 0.6s ease-out;
17	      --color-mode-1-rgb: 255, 107, 157;
18	      --color-mode-2-rgb: 78, 205, 196;
19	      --color-mode-3-rgb: 149, 225, 211;
20	    }
21	
22	    * {
23	      margin: 0;
24	      padding: 0;
25	      box-sizing: border-box;
26	    }
27	    html, body {
28	      width: 100%;
29	      height: 100%;
30	      overflow: hidden;
31	    }
32	    body {
33	      display: flex;
34	      flex-direction: column;
35	      justify-content: center;
36	      align-items: center;
37	      gap: 20px;
38	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
39	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
40	      color: var(--color-white);
41	      font-size: 14px;
42	      text-align: center;
43	      padding: 20px;
44	    }
45	    .circle-container {
46	      cursor: pointer;
47	      border: none;
48	      background: none;
49	      padding: 0;
50	      position: relative;
51	      will-change: transform;
52	    }
53	    .circle-container:hover,
54	    .circle-container:focus-visible {
55	      transform: scale(1.08);
56	    }
57	    .circle-container:focus {
58	      outline: none;
59	    }
60	    .circle-container:focus-visible {
61	      outline: 3px solid rgba(255, 255, 255, 0.7);
62	      outline-offset: 12px;
63	      border-radius: 50%;
64	    }
65	    svg {
66	      width: min(400px, 80vw);
67	      height: min(400px, 80vw);
68	      display: block;
69	      animation: fadeIn var(--transition-slow);
70	    }
71	    circle {
72	      fill: var(--color-white);
73	      stroke: rgba(255, 255, 255, 0.2);
74	      stroke-width: 2;
75	      animation: pulse 3s ease-in-out infinite;
76	      filter: drop-shadow(0 20px 40px var(--shadow-color));
77	      transition: fill var(--transition-normal), r 0.3s ease, stroke var(--transition-normal), filter var(--transition-normal);
78	    }
79	    .circle-container:hover circle,
80	    .circle-container:focus-visible circle {
81	      fill: #e8f4f8;
82	      r: 205;
83	      stroke: rgba(255, 255, 255, 0.4);
84	    }
85	    .circle-container.active circle {
86	      fill: var(--color-gold);
87	      stroke: rgba(255, 215, 0, 0.3);
88	      animation: pulse-active 0.6s ease-in-out;
89	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
90	    }
91	    .circle-container.active:hover circle {
92	      fill: #ffed4e;
93	    }
94	
95	    .circle-container.color-mode-1 circle {
96	      fill: var(--color-pink);
97	      stroke: rgba(var(--color-mode-1-rgb), 0.3);
98	      filter: drop-shadow(0 20px 40px rgba(var(--color-mode-1-rgb), 0.3));
99	    }
100	    .circle-container.color-mode-1:hover circle,
101	    .circle-container.color-mode-1:focus-visible circle {
102	      stroke: rgba(var(--color-mode-1-rgb), 0.5);
103	    }
104	    .circle-container.color-mode-1.active circle {
105	      filter: drop-shadow(0 20px 40px rgba(var(--color-mode-1-rgb), 0.5));
106	    }
107	
108	    .circle-container.color-mode-2 circle {
109	      fill: var(--color-teal);
110	      stroke: rgba(var(--color-mode-2-rgb), 0.3);
111	      filter: drop-shadow(0 20px 40px rgba(var(--color-mode-2-rgb), 0.3));
112	    }
113	    .circle-container.color-mode-2:hover circle,
114	    .circle-container.color-mode-2:focus-visible circle {
115	      stroke: rgba(var(--color-mode-2-rgb), 0.5);
116	    }
117	    .circle-container.color-mode-2.active circle {
118	      filter: drop-shadow(0 20px 40px rgba(var(--color-mode-2-rgb), 0.5));
119	    }
120	
121	    .circle-container.color-mode-3 circle {
122	      fill: var(--color-mint);
123	      stroke: rgba(var(--color-mode-3-rgb), 0.3);
124	      filter: drop-shadow(0 20px 40px rgba(var(--color-mode-3-rgb), 0.3));
125	    }
126	    .circle-container.color-mode-3:hover circle,
127	    .circle-container.color-mode-3:focus-visible circle {
128	      stroke: rgba(var(--color-mode-3-rgb), 0.5);
129	    }
130	    .circle-container.color-mode-3.active circle {
131	      filter: drop-shadow(0 20px 40px rgba(var(--color-mode-3-rgb), 0.5));
132	    }
133	
134	    .hint {
135	      font-size: 12px;
136	      opacity: 0.85;
137	      transition: opacity var(--transition-normal);
138	      letter-spacing: 0.5px;
139	      max-width: 90%;
140	    }
141	    .circle-container:hover ~ .hint,
142	    .circle-container:focus-visible ~ .hint {
143	      opacity: 1;
144	    }
145	
146	    .mode-indicator {
147	      font-size: 10px;
148	      opacity: 0;
149	      margin-top: 8px;
150	      letter-spacing: 1px;
151	      text-transform: uppercase;
152	      transition: opacity var(--transition-normal);
153	      height: 16px;
154	    }
155	    .mode-indicator.visible {
156	      opacity: 0.9;
157	    }
158	
159	    .controls {
160	      display: flex;
161	      gap: 12px;
162	      margin-top: 8px;
163	    }
164	
165	    .control-btn {
166	      padding: 8px 16px;
167	      font-size: 11px;
168	      font-weight: 600;
169	      letter-spacing: 0.5px;
170	      text-transform: uppercase;
171	      background: rgba(255, 255, 255, 0.15);
172	      color: var(--color-white);
173	      border: 1px solid rgba(255, 255, 255, 0.3);
174	      border-radius: 20px;
175	      cursor: pointer;
176	      transition: all var(--transition-normal);
177	      backdrop-filter: blur(4px);
178	      will-change: transform;
179	    }
180	
181	    .control-btn:hover {
182	      background: rgba(255, 255, 255, 0.25);
183	      border-color: rgba(255, 255, 255, 0.5);
184	      transform: translateY(-2px);
185	    }
186	
187	    .control-btn:active {
188	      transform: scale(0.95);
189	    }
190	
191	    .control-btn:focus {
192	      outline: none;
193	    }
194	
195	    .control-btn:focus-visible {
196	      outline: 2px solid rgba(255, 255, 255, 0.7);
197	      outline-offset: 4px;
198	    }
199	    @keyframes pulse {
200	      0%, 100% { r: 200; }
201	      50% { r: 202; }
202	    }
203	    @keyframes pulse-active {
204	      0% { r: 200; }
205	      50% { r: 210; }
206	      100% { r: 200; }
207	    }
208	    @keyframes fadeIn {
209	      from { opacity: 0; transform: scale(0.9); }
210	      to { opacity: 1; transform: scale(1); }
211	    }
212	    @keyframes colorShift {
213	      0% { filter: brightness(1); }
214	      50% { filter: brightness(1.2); }
215	      100% { filter: brightness(1); }
216	    }
217	    .color-shifting circle {
218	      animation: colorShift 0.6s ease-out;
219	    }
220	    @media (max-width: 480px) {
221	      body {
222	        gap: 16px;
223	      }
224	      .hint {
225	        font-size: 11px;
226	      }
227	      .mode-indicator {
228	        font-size: 9px;
229	      }
230	    }
231	    @media (prefers-reduced-motion: reduce) {
232	      * {
233	        animation: none !important;
234	        transition: none !important;
235	      }
236	    }
237	  </style>
238	</head>
239	<body>
240	  <main style="text-align: center;">
241	    <h1 style="position: absolute; width: 1px; height: 1px; overflow: hidden;">Circle Display</h1>
242	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle">
243	      <svg viewBox="0 0 400 400" aria-hidden="true">
244	        <circle cx="200" cy="200" r="200"/>
245	      </svg>
246	    </button>
247	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
248	    <div class="controls">
249	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
250	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
251	    </div>
252	  </main>
253	  <div class="hint" id="hint-text" role="status" aria-live="polite">Click to activate • Double-click to change color</div>
254	
255	  <script>
256	    const STORAGE_KEY = 'circle-state';
257	    const COLOR_MODES = ['default', 'color-mode-1', 'color-mode-2', 'color-mode-3'];
258	    const COLOR_NAMES = ['Default White', 'Pink', 'Teal', 'Mint'];
259	
260	    const circle = document.getElementById('decorative-circle');
261	    const hint = document.getElementById('hint-text');
262	    const modeIndicator = document.getElementById('mode-indicator');
263	    const cycleBtn = document.getElementById('cycle-btn');
264	    const resetBtn = document.getElementById('reset-btn');
265	
266	    let state = { active: false, colorMode: 0 };
267	    let lastTapTime = 0;
268	    const TAP_DELAY = 300;
269	
270	    const saveState = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
271	
272	    const loadState = () => {
273	      try {
274	        const saved = localStorage.getItem(STORAGE_KEY);
275	        if (saved) state = JSON.parse(saved);
276	      } catch (e) {
277	        console.warn('Failed to load state');
278	      }
279	      applyState();
280	    };
281	
282	    const applyState = () => {
283	      circle.classList.remove('active', ...COLOR_MODES);
284	      if (state.active) circle.classList.add('active');
285	      if (state.colorMode > 0) circle.classList.add(COLOR_MODES[state.colorMode]);
286	      updateUI();
287	    };
288	
289	    const toggleActive = () => {
290	      state.active = !state.active;
291	      applyState();
292	      saveState();
293	    };
294	
295	    const cycleColor = () => {
296	      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
297	      state.active = true;
298	      circle.classList.add('color-shifting');
299	      setTimeout(() => circle.classList.remove('color-shifting'), 600);
300	      applyState();
301	      saveState();
302	    };
303	
304	    const resetState = () => {
305	      state = { active: false, colorMode: 0 };
306	      applyState();
307	      saveState();
308	    };
309	
310	    const updateUI = () => {
311	      const isTouchDevice = () => {
312	        return (('ontouchstart' in window) ||
313	                (navigator.maxTouchPoints > 0) ||
314	                (navigator.msMaxTouchPoints > 0));
315	      };
316	
317	      const isTouch = isTouchDevice();
318	      const hints = state.active
319	        ? ['Active!', isTouch ? 'Tap again to change color' : 'Double-click or press C to change color', isTouch ? 'Use Reset button' : 'Press R to reset']
320	        : ['Click to activate', isTouch ? 'Tap twice to cycle color' : 'Double-click or press C to cycle color', 'Use Reset button'];
321	      hint.textContent = hints.join(' • ');
322	
323	      if (state.active && state.colorMode > 0) {
324	        modeIndicator.textContent = COLOR_NAMES[state.colorMode];
325	        modeIndicator.classList.add('visible');
326	      } else {
327	        modeIndicator.classList.remove('visible');
328	      }
329	    };
330	
331	    circle.addEventListener('click', toggleActive);
332	    circle.addEventListener('dblclick', (e) => {
333	      e.preventDefault();
334	      cycleColor();
335	    });
336	
337	    circle.addEventListener('touchend', (e) => {
338	      const currentTime = Date.now();
339	      const tapLength = currentTime - lastTapTime;
340	      if (tapLength < TAP_DELAY && tapLength > 0) {
341	        e.preventDefault();
342	        cycleColor();
343	      } else {
344	        lastTapTime = currentTime;
345	      }
346	    });
347	
348	    circle.addEventListener('keydown', (e) => {
349	      const key = e.key.toLowerCase();
350	      if (key === ' ' || key === 'enter') {
351	        e.preventDefault();
352	        toggleActive();
353	      } else if (key === 'c') {
354	        e.preventDefault();
355	        cycleColor();
356	      } else if (key === 'r') {
357	        e.preventDefault();
358	        resetState();
359	      }
360	    });
361	
362	    cycleBtn.addEventListener('click', cycleColor);
363	    resetBtn.addEventListener('click', resetState);
364	
365	    loadState();
366	    circle.focus();
367	  </script>
368	</body>
369	</html>
